  constructor() {
    this.cache = new Map();
    this.pendingPromises = new Map(); // 用于存储进行中的异步操作
  }

  async getData(key) {
    // 第一重检查：如果缓存中已有数据，直接返回
    if (this.cache.has(key)) {
      return this.cache.get(key);
    }

    // 第二重检查：如果已有进行中的异步操作，等待其结果
    if (this.pendingPromises.has(key)) {
      return this.pendingPromises.get(key);
    }

