      this.cache.set(key, data);
      this.pendingPromises.delete(key); // 操作完成后移除
      return data;
    }).catch(error => {
      this.pendingPromises.delete(key); // 出错时也移除，避免阻塞后续请求
      throw error;
    });

    this.pendingPromises.set(key, promise);
    return promise;
  }

  async fetchData(key) {
    // 模拟异步数据获取
    await new Promise(resolve => setTimeout(resolve, 500));
    return `data for ${key}`;
  }

  // 可选：添加缓存清理方法
  clearCache() {
    this.cache.clear();
    this.pendingPromises.clear();
  }
}

// 使用示例
const cache = new DataCache();
async function example() {
  const promises = [];
  for (let i = 0; i < 5; i++) {
    promises.push(cache.getData('user'));
  }
  const results = await Promise.all(promises);
  console.log(results); // 所有结果相同，只调用一次 fetchData
}
