        }
        return response.body();
    }

    public static void main(String[] args) {
        SimpleHttpClient client = new SimpleHttpClient();
        try {
            String response = client.get("https://api.example.com/data");
            System.out.println("GET Response: " + response);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
