const { db, cache, externalService } = require('./dependencies');

async function checkDatabase() {
    try {
        const result = await db.query('SELECT 1');
        return { service: 'database', status: 'healthy', details: { queryTime: result[0].duration } };
    } catch (error) {
        throw new Error(`Database health check failed: ${error.message}`);
    }
}

async function checkCache() {
    try {
        await cache.ping();
        return { service: 'redis', status: 'healthy' };
    } catch (error) {
        throw new Error(`Cache health check failed: ${error.message}`);
    }
}

async function checkExternalService() {
    try {
        const response = await externalService.getStatus();
        if (response.status !== 'OK') {
            throw new Error(`Service returned status: ${response.status}`);
        }
        return { service: 'external-api', status: 'healthy', details: { latency: response.latencyMs } };
    } catch (error) {
        throw new Error(`External service health check failed: ${error.message}`);
    }
}

router.get('/health', async (req, res) => {
    const checks = [];
    const checkPromises = [
        checkDatabase(),
        checkCache(),
        checkExternalService()
    ];

    try {
        const results = await Promise.allSettled(checkPromises);

        results.forEach((result) => {
            if (result.status === 'fulfilled') {
                checks.push(result.value);
            } else {
                checks.push({
                    service: 'unknown', // Could be determined from the error message
                    status: 'unhealthy',
                    error: result.reason.message
                });
            }
        });

        const allHealthy = checks.every(c => c.status === 'healthy');
        const statusCode = allHealthy ? 200 : 503;

        res.status(statusCode).json({
            status: allHealthy ? 'ok' : 'degraded',
            timestamp: new Date().toISOString(),
            checks
        });

    } catch (unexpectedError) {
        console.error('Unexpected error in health endpoint:', unexpectedError);
        res.status(500).json({
            status: 'error',
            message: 'Internal server error during health check'
        });
    }
});

