// 定义一个简单的文件系统树节点接口
interface FileNode {
  name: string;
  size: number;
  isDirectory: boolean;
  children?: FileNode[];
}

/**
 * 使用记忆化（Memoization）优化计算文件树总大小。
 * 通过Map缓存已计算节点的结果，避免对同一子树的重复遍历。
 * @param node 文件树的根节点
 * @param cache 用于存储节点->总大小的映射缓存
 * @returns 以字节为单位的总大小
 */
function getTotalSizeMemoized(node: FileNode, cache: Map<FileNode, number> = new Map()): number {
  // 如果缓存中已有该节点的计算结果，直接返回
  if (cache.has(node)) {
    return cache.get(node)!;
  }

  // 如果是文件，直接返回大小并缓存
  if (!node.isDirectory) {
    cache.set(node, node.size);
    return node.size;
  }

  // 对于目录，递归计算子节点，但利用缓存
  let totalSize = 0;
  if (node.children && node.children.length > 0) {
    for (const child of node.children) {
      // 递归调用时传入同一个缓存Map
      totalSize += getTotalSizeMemoized(child, cache);
    }
  }
  // 将目录节点的总大小存入缓存
  cache.set(node, totalSize);
  return totalSize;
}

